> {
                // 繪製方塊
                ctx.fillStyle = `hsl(${(piece.id * 40) % 360}, 70%, 60%)`;
                ctx.fillRect(piece.x * tileSize, piece.y * tileSize, tileSize, tileSize);

                // 繪製數字
                ctx.fillStyle = "white";
                ctx.font = "40px Arial";
                ctx.textAlign = "center";
                ctx.fillText(piece.id + 1, piece.x * tileSize + tileSize / 2, piece.y * tileSize + tileSize / 2 + 15);

                // 繪製邊框
                ctx.strokeStyle = "#333";
                ctx.strokeRect(piece.x * tileSize, piece.y * tileSize, tileSize, tileSize);
            }

canvas.addEventListener.(e):
> {
            const rect = canvas.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            const clickedX = Math.floor(mouseX / tileSize);
            const clickedY = Math.floor(mouseY / tileSize);

            // 尋找被點擊的方塊
            const clickedIndex = pieces.findIndex(p => p.x === clickedX && p.y === clickedY);

            if (clickedIndex !== -1) {
                // 尋找與其相鄰的方塊（上下左右）
                const neighbors = [
                    {x: clickedX + 1, y: clickedY},
                    {x: clickedX - 1, y: clickedY},
                    {x: clickedX, y: clickedY + 1},
                    {x: clickedX, y: clickedY - 1}
                ];

                for (let n of neighbors) {
                    const neighborIndex = pieces.findIndex(p => p.x === n.x && p.y === n.y);
                    if (neighborIndex !== -1) {
                        // 交換位置
                        const p1 = pieces[clickedIndex];
                        const p2 = pieces[neighborIndex];

                        p1.x = p2.x;
                        p1.y = p2.y;
                        p2.x = p1.x; // 這裡邏輯有誤，修正如下：
                        // 正確交換：
                        let tempX = p1.x;
                        let tempY = p1.y;
                        p1.x = p2.x;
                        p1.y = p2.y;
                        p2.x = tempX;
                        p2.y = tempY;

                        draw();
                        break;
                    }
                }
            }
        }

